local ModuleToastDialog = Class("ModuleToastDialog")

------------ lifeCycle ------------

function ModuleToastDialog:__init()
    self:CleanField()
    self.moduleId = 0
end

function ModuleToastDialog:__delete()
    self:CleanField()
    self.controller = nil
end

function ModuleToastDialog:CleanField()
    self.moduleId = nil
end

function ModuleToastDialog:Awake()
    local argument = self.controller.Argument
    if argument ~= nil and argument.parameters ~= nil then
        self.moduleId = checkNumber(argument.parameters.moduleId)
    end
    SetButtonAction(self.CloseButton, function()
        KTool.SafeDelete(self.controller.gameObject)
    end)
    SetButtonAction(self.EmptyBg, function()
        KTool.SafeDelete(self.controller.gameObject)
    end)
end

function ModuleToastDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
       
        self:SetRuleInfoDesc()
    end))
    return coWait
end

function ModuleToastDialog:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

------------ lifeCycle ------------

function ModuleToastDialog:SetRuleInfoDesc()
    local desc = self:GetModuleRuleInfoData(self.moduleId)
    if isNull(desc) then return end
    desc = checkString(desc)
    desc = string.gsub(desc, "\\n", "\n")
    self.TxtDesc.text = desc
end

function ModuleToastDialog:SetModuleId(moduleId)
    self.moduleId = tonumber(moduleId)
    self:SetRuleInfoDesc()
end

function ModuleToastDialog:SetRuleInfoDesc2(desc)
    self.TxtDesc.text = desc
end

function ModuleToastDialog:GetModuleRuleInfoData(moduleId)
    moduleId = checkNumber(moduleId)
    local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting12)
    local length = tableFile:GetRowCount()
    for i = 1, length do
        local row = tableFile:GetRow(i)
        local idInConfig = checkNumber(row:Get('Id'))
        if moduleId == idInConfig then
            -- return checkString(row:Get('descr'))
            return parse_localizeText(row, "descr", true, "")
        end
    end
    return nil
end

return ModuleToastDialog